// === Tab: circleCrossPoints ===
// Ported from Processing codes in the below gist by zawa-works.
// https://gist.github.com/zawa-works/534fec44dd938ad9707264d1a984c6c5#file-getcirclescrosspoints-pde
// https://zawaworks.hatenablog.com/entry/2020/01/06/014618

// Get cross points of 2 circles
const getCirclesCrossPoints = (x1, y1, r1, x2, y2, r2) => {
  const a = 2 * (x2 - x1);
  const b = 2 * (y2 - y1);
  const c = sq(x1) - sq(x2) + sq(y1) - sq(y2) + sq(r2) - sq(r1);
  return getLineCircleCrossPoints(a, b, c, x1, y1, r1);
}

// Get cross points of a line(ax + by + c = 0) and a circle(center: (circleX, circleY) radius: r)
const getLineCircleCrossPoints = (a, b, c, circleX, circleY, r) => {
  // Distance from the center of the circle to the line.
  const d = abs((a * circleX + b * circleY + c) / mag(a, b));
  let theta = atan2(b, a);
  const crossPoints = [];

  if (d > r) {
    // No intersection
  } else if (d === r) {
    // Single intersection point
    if (a * circleX + b * circleY + c > 0) theta += PI;

    const crossX = r * cos(theta) + circleX;
    const crossY = r * sin(theta) + circleY;

    crossPoints.push(createVector(crossX, crossY));
  } else {
    // 2 intersection points
    const crossX = [0, 0];
    const crossY = [0, 0];

    const phi = acos(d / r);
    let alpha = theta - phi;
    let beta = theta + phi;

    if (a * circleX + b * circleY + c > 0) {
      alpha += PI;
      beta += PI;
    }

    crossX[0] = r * cos(alpha) + circleX;
    crossY[0] = r * sin(alpha) + circleY;

    crossX[1] = r * cos(beta) + circleX;
    crossY[1] = r * sin(beta) + circleY;

    for (let i = 0; i < 2; i++) {
      crossPoints.push(createVector(crossX[i], crossY[i]));
    }
  }

  return crossPoints;
}


// === Tab: texture ===
let textureGfx;
const prepareTexture = (w,h) => {
  textureGfx = createGraphics(w,h);
  textureGfx.noStroke();

  // white texture
  const textureColor = color(255);
  textureColor.setAlpha(30);
  textureGfx.fill(textureColor);
  for (let i = 0; i < 100000; i++) {
    textureGfx.circle(random(w), random(h), (noise(i) * w) / 360);
  }
};

